{
  "name": "@kohai-ai/opencode",
  "version": "0.1.0-beta.1",
  "license": "MIT",
  "type": "module",
  "description": "OpenCode plugin for signing in to Kohai with a device code and using Kohai Coder models.",
  "main": "./dist/index.js",
  "exports": {
    ".": "./dist/index.js"
  },
  "files": [
    "dist"
  ],
  "engines": {
    "node": ">=22"
  },
  "scripts": {
    "build": "tsup",
    "typecheck": "tsc --noEmit",
    "test": "vitest run",
    "prepublishOnly": "pnpm build && bash scripts/check-opencode-version.sh 1.18.34 && bash scripts/check-opencode-version.sh latest"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "1.18.34",
    "@opencode/plugin": "2.0.32",
    "@types/node": "^22.10.0",
    "tsup": "^8.5.0",
    "typescript": "^5.9.3",
    "vitest": "^4.1.6"
  },
  "publishConfig": {
    "access": "public"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/BasedAICo/hirebase.git",
    "directory": "packages/opencode-kohai"
  },
  "homepage": "https://help.kohai.co/coding-clis/use-kohai-from-opencode",
  "keywords": [
    "opencode",
    "plugin",
    "kohai"
  ]
}
